ALTER TABLE stock_operational.user_state ADD CONSTRAINT user_state_deleted_at_range CHECK ("deletedAt" IS NULL OR ("deletedAt">=TIMESTAMPTZ '0001-01-01 00:00:00+00' AND "deletedAt"<TIMESTAMPTZ '10000-01-01 00:00:00+00'));
CREATE UNIQUE INDEX active_order_shipment ON stock_operational.shipment_orders("orderId") WHERE "deletedAt" IS NULL;
DO $replace$ DECLARE definition text; old_body text; BEGIN
 SELECT pg_get_functiondef(oid),prosrc INTO STRICT definition,old_body FROM pg_proc WHERE oid='stock_operational.prepare_record_write()'::regprocedure;
 IF (length(definition)-length(replace(definition,old_body,'')))/length(old_body)<>1 THEN RAISE EXCEPTION 'Ambiguous function body'; END IF;
 EXECUTE replace(definition,old_body,'
DECLARE shape jsonb; blanks jsonb;
BEGIN
 IF TG_TABLE_SCHEMA<>''stock_operational'' OR TG_WHEN<>''BEFORE'' OR TG_LEVEL<>''ROW''
 OR TG_OP NOT IN (''INSERT'',''UPDATE'') OR TG_NARGS<1 THEN
  RAISE EXCEPTION ''Unsupported record write guard'';
 END IF;
 shape := to_jsonb(NEW);
 -- Only explicitly listed text columns are normalized. No full-row JSON
 -- reconstruction, numeric rounding, timestamp parsing or metadata edits.
 SELECT jsonb_object_agg(name,''null''::jsonb) INTO blanks
 FROM unnest(TG_ARGV[1:TG_NARGS-1]) AS fields(name)
 WHERE shape->name=''""''::jsonb;
 IF blanks IS NOT NULL THEN
  NEW := jsonb_populate_record(NEW,blanks);
  shape := shape || blanks;
 END IF;
 IF TG_OP=''UPDATE'' THEN
  IF shape->TG_ARGV[0] IS DISTINCT FROM to_jsonb(OLD)->TG_ARGV[0]
  OR OLD."deletedAt" IS NOT NULL THEN
   RAISE EXCEPTION ''Immutable identity, order or deleted record'';
  END IF;
  NEW.revision := OLD.revision+1;
 END IF;
 RETURN NEW;
END ');
END $replace$;
CREATE FUNCTION stock_operational.soft_delete_contract_v1() RETURNS text LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='' AS $$
BEGIN
 IF (SELECT count(*)<>23 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid
 WHERE c.relnamespace='stock_operational'::regnamespace AND c.relname IN ('orders','order_items','order_bills','shipments','shipment_orders','employees','employee_compensations','employee_timesheets','employee_advances','payroll_settlements','expenses','expense_categories','shops','sales_receipts','sales_receipt_items','sales_receipt_payments','sales_receipt_syncs','sales_profit_cost_overrides','stock_counts','stock_adjustments','movements','movement_details','user_state')
 AND a.attname='deletedAt' AND a.atttypid='timestamptz'::regtype AND NOT a.attisdropped)
 OR EXISTS(SELECT FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid
 WHERE c.relnamespace='stock_operational'::regnamespace AND c.relname IN ('orders','order_items','order_bills','shipments','shipment_orders','employees','employee_compensations','employee_timesheets','employee_advances','payroll_settlements','expenses','expense_categories','shops','sales_receipts','sales_receipt_items','sales_receipt_payments','sales_receipt_syncs','sales_profit_cost_overrides','stock_counts','stock_adjustments','movements','movement_details','user_state')
 AND a.attname='archived_at' AND NOT a.attisdropped)
 OR (SELECT count(*)<>23 FROM pg_trigger WHERE tgname='a_validate' AND tgenabled='O'
 AND tgfoid='stock_operational.prepare_record_write()'::regprocedure AND tgrelid IN ('stock_operational.orders'::regclass,'stock_operational.order_items'::regclass,'stock_operational.order_bills'::regclass,'stock_operational.shipments'::regclass,'stock_operational.shipment_orders'::regclass,'stock_operational.employees'::regclass,'stock_operational.employee_compensations'::regclass,'stock_operational.employee_timesheets'::regclass,'stock_operational.employee_advances'::regclass,'stock_operational.payroll_settlements'::regclass,'stock_operational.expenses'::regclass,'stock_operational.expense_categories'::regclass,'stock_operational.shops'::regclass,'stock_operational.sales_receipts'::regclass,'stock_operational.sales_receipt_items'::regclass,'stock_operational.sales_receipt_payments'::regclass,'stock_operational.sales_receipt_syncs'::regclass,'stock_operational.sales_profit_cost_overrides'::regclass,'stock_operational.stock_counts'::regclass,'stock_operational.stock_adjustments'::regclass,'stock_operational.movements'::regclass,'stock_operational.movement_details'::regclass,'stock_operational.user_state'::regclass))
 OR (SELECT md5(prosrc)<>'6645ebc280c884f32de85d94ea3fe957' OR prosecdef
 FROM pg_proc WHERE oid='stock_operational.prepare_record_write()'::regprocedure)
 THEN RAISE EXCEPTION 'Incomplete deletedAt schema'; END IF;
 RETURN 'deletedAt';
END $$;
-- Copy the existing private read-contract ACL, including grant options.
DO $acl$ DECLARE a record; caller text; BEGIN
 FOR a IN SELECT * FROM aclexplode((SELECT coalesce(proacl,acldefault('f',proowner)) FROM pg_proc WHERE oid='stock_operational.soft_delete_contract_v1()'::regprocedure)) LOOP
  caller:=CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(a.grantee)) END;
  EXECUTE 'REVOKE ALL ON FUNCTION stock_operational.soft_delete_contract_v1() FROM '||caller;
 END LOOP;
 FOR a IN SELECT * FROM aclexplode((SELECT coalesce(proacl,acldefault('f',proowner)) FROM pg_proc WHERE oid='stock_operational.lexeme_mapping_contract_v1()'::regprocedure)) LOOP
  IF a.grantee=0 OR pg_get_userbyid(a.grantee) IN ('anon','authenticated') THEN RAISE EXCEPTION 'Unreviewed public contract access'; END IF;
  EXECUTE format('GRANT EXECUTE ON FUNCTION stock_operational.soft_delete_contract_v1() TO %I%s',pg_get_userbyid(a.grantee),CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END);
 END LOOP;
END $acl$;
